create policy "lesson videos read" on storage.objects for select to authenticated using (bucket_id = 'lesson-videos');
create policy "lesson videos admin insert" on storage.objects for insert to authenticated with check (bucket_id = 'lesson-videos' and public.has_role(auth.uid(), 'admin'));
create policy "lesson videos admin update" on storage.objects for update to authenticated using (bucket_id = 'lesson-videos' and public.has_role(auth.uid(), 'admin'));
create policy "lesson videos admin delete" on storage.objects for delete to authenticated using (bucket_id = 'lesson-videos' and public.has_role(auth.uid(), 'admin'));